def _i(code, herb, severity, itype, mechanism, effect, management, grade, sources, drug=None, drug_class=None, timing=None, flags=None, en=None, hi=None):
    assert (drug is None) != (drug_class is None), f"{code}: exactly one of drug / drug_class"
    return {
        "code": code, "herb": herb, "drug": drug, "drug_class": drug_class, "severity": severity, "interaction_type": itype,
        "mechanism": mechanism, "effect": effect, "management": management, "timing_gap_hours": timing, "evidence_grade": grade,
        "population_flags": flags or [], "sources": sources, "patient_summary_en": en, "patient_summary_hi": hi,
    }


